1	{
2	  "$schema": "https://json-schema.org/draft/2020-12/schema",
3	  "type": "object",
4	  "required": ["results"],
5	  "properties": {
6	    "results": {
7	      "type": "array",
8	      "minItems": 1,
9	      "maxItems": 24,
10	      "items": {
11	        "type": "object",
12	        "required": ["candidate_id", "relevant", "score", "reason"],
13	        "properties": {
14	          "candidate_id": {"type": "string", "minLength": 1},
15	          "relevant": {"type": "boolean"},
16	          "score": {"type": "number", "minimum": 0, "maximum": 100},
17	          "reason": {"type": "string", "minLength": 1},
18	          "fulltext_required": {"type": "boolean"},
19	          "topic_fit": {"enum": ["direct", "adjacent", "tangential", "off_topic"]},
20	          "core_contribution": {"type": "string", "minLength": 1, "maxLength": 80},
21	          "matched_direction_id": {"type": "string", "minLength": 1, "maxLength": 120},
22	          "boundary_conflict": {"type": "boolean"},
23	          "technology_value": {
24	            "type": "object",
25	            "required": ["novelty", "architecture_impact", "industry_signal", "project_alignment"],
26	            "properties": {
27	              "novelty": {"$ref": "#/$defs/value_dimension"},
28	              "architecture_impact": {"$ref": "#/$defs/value_dimension"},
29	              "industry_signal": {"$ref": "#/$defs/value_dimension"},
30	              "project_alignment": {"$ref": "#/$defs/value_dimension"}
31	            },
32	            "additionalProperties": false
33	          },
34	          "matched_signals": {
35	            "type": "array",
36	            "items": {"type": "string"},
37	            "maxItems": 8
38	          }
39	        },
40	        "additionalProperties": false
41	      }
42	    }
43	  },
44	  "$defs": {
45	    "value_dimension": {
46	      "type": "object",
47	      "required": ["score", "reason"],
48	      "properties": {
49	        "score": {"type": "number", "minimum": 0, "maximum": 5},
50	        "reason": {"type": "string", "minLength": 1, "maxLength": 240}
51	      },
52	      "additionalProperties": false
53	    }
54	  },
55	  "additionalProperties": false
56	}
